// Generated by `just generate` from `src/plugins/dotclaude-lab/slices/capture/domain/report.ts`. Edit the source and run `just generate`.
// Request sizing for `dotclaude-capture`: split a request into parts and count each
// part with the `count_tokens` endpoint. The CLI writes the result.

import type {
  Block,
  Body,
  CountReply,
  Fix,
  Message,
  Part,
  Row,
  Sizing,
  Swap,
  Tool,
} from "./types.ts";

/** The label of one content block: its type and its first words. */
const label = (block: Block | string): string => {
  if (typeof block === "string") return `text: ${block.slice(0, 70)}`;
  const text = block.text ?? block.content ?? block.name ?? "";
  const head = (typeof text === "string" ? text : JSON.stringify(text)).replace(
    /\s+/g,
    " ",
  );
  return `${block.type}: ${head.slice(0, 70)}`;
};

const asBlocks = (content: string | Block[]): Block[] =>
  typeof content === "string" ? [{ type: "text", text: content }] : content;

// A text longer than this is sized by section, not as one block.
const SPLIT_CHARS = 2000;
// A line that starts a section: a heading, an opening tag, or a listing.
const SECTION =
  /^(#{1,3} \S|<[a-z_-]+>\s*$|The following |Available agent types|While auto mode)/;

/** The sections of a text: each one starts at a SECTION line. */
const sections = (text: string): string[] => {
  const lines = text.split("\n");
  const found: string[] = [];
  let from = 0;
  lines.forEach((line, i) => {
    if (i > 0 && SECTION.test(line)) {
      found.push(lines.slice(from, i).join("\n"));
      from = i;
    }
  });
  found.push(lines.slice(from).join("\n"));
  return found;
};

/**
 * The parts of one content block. A long text block gives one part for each
 * section, and `swap` returns the request with the block replaced.
 */
const blockParts = (
  kind: string,
  block: Block,
  swap: Swap,
  removable: boolean,
): Part[] => {
  const text = typeof block.text === "string" ? block.text : null;
  if (text && text.length > SPLIT_CHARS) {
    const list = sections(text);
    if (list.length > 1) {
      return list.map((section, i) => ({
        kind,
        name: label({ type: "section", text: section }),
        chars: section.length,
        without: () =>
          swap({ ...block, text: list.filter((_, j) => j !== i).join("\n") }),
      }));
    }
  }
  if (!removable) return [];
  return [
    {
      kind,
      name: label(block),
      chars: JSON.stringify(block).length,
      without: () => swap(null),
    },
  ];
};

/** The parts of a request, each with a function that returns the request without it. */
export const parts = (body: Body): Part[] => {
  const list: Part[] = [];
  const system = asBlocks(body.system ?? []);
  system.forEach((block, i) => {
    const swap: Swap = (next) => ({
      ...body,
      system: system.flatMap((b, j) => (j !== i ? [b] : next ? [next] : [])),
    });
    list.push(...blockParts("system", block, swap, true));
  });
  (body.tools ?? []).forEach((tool: Tool, i) => {
    list.push({
      kind: tool.defer_loading ? "tool (deferred)" : "tool",
      name: tool.name ?? tool.type,
      chars: JSON.stringify(tool).length,
      without: () => ({
        ...body,
        tools: (body.tools as Tool[]).filter((_, j) => j !== i),
      }),
    });
  });
  body.messages.forEach((message: Message, m) => {
    const blocks = asBlocks(message.content);
    blocks.forEach((block, b) => {
      const swap: Swap = (next) => ({
        ...body,
        messages: body.messages.map((msg, j) =>
          j === m
            ? {
                ...msg,
                content: blocks.flatMap((x, k) =>
                  k !== b ? [x] : next ? [next] : [],
                ),
              }
            : msg,
        ),
      });
      // A message needs one block, so the only block of a message is not removed.
      list.push(
        ...blockParts(
          `message ${m} (${message.role})`,
          block,
          swap,
          blocks.length > 1,
        ),
      );
    });
  });
  return list;
};

/** The fields that `count_tokens` takes. */
const countable = (body: Body) => {
  const { model, system, tools, messages, thinking, tool_choice } = body;
  return { model, system, tools, messages, thinking, tool_choice };
};

// Changes that make a body acceptable to `count_tokens`, tried in this order
// when it refuses the body as sent. The report names the changes in use.
const FIXES: Record<string, Fix> = {
  "no thinking": (body) => ({ ...body, thinking: undefined }),
  "system messages as user text": (body) => {
    const messages: Message[] = [];
    for (const msg of body.messages) {
      const last = messages.at(-1);
      if (msg.role !== "system") messages.push({ ...msg });
      else if (last?.role === "user")
        last.content = [...asBlocks(last.content), ...asBlocks(msg.content)];
      else messages.push({ role: "user", content: asBlocks(msg.content) });
    }
    return { ...body, messages };
  },
};

const countTokens = async (
  upstream: string,
  body: Body,
  headers: Record<string, string>,
  query: string,
): Promise<number> => {
  const res = await fetch(`${upstream}/v1/messages/count_tokens${query}`, {
    method: "POST",
    headers,
    body: JSON.stringify(countable(body)),
  });
  const json = (await res.json()) as CountReply;
  if (!res.ok)
    throw new Error(
      `count_tokens ${res.status}: ${JSON.stringify(json).slice(0, 300)}`,
    );
  return json.input_tokens;
};

/** The fixes that `count_tokens` needs for this body, and the count with them. */
const fixesFor = async (
  upstream: string,
  body: Body,
  headers: Record<string, string>,
  query: string,
): Promise<{ used: string[]; full: number }> => {
  const used: string[] = [];
  const errors: string[] = [];
  for (const name of [null, ...Object.keys(FIXES)]) {
    if (name) used.push(name);
    const fixed = used.reduce((b, f) => (FIXES[f] as Fix)(b), body);
    try {
      return { used, full: await countTokens(upstream, fixed, headers, query) };
    } catch (e) {
      errors.push(String(e));
    }
  }
  throw new Error(errors.join("\n"));
};

/** Sizes one request: the full count, then the count without each part. */
export const sizeRequest = async (
  upstream: string,
  body: Body,
  headers: Record<string, string>,
  query: string,
): Promise<Sizing> => {
  const { used, full } = await fixesFor(upstream, body, headers, query);
  const fix = (b: Body): Body => used.reduce((x, f) => (FIXES[f] as Fix)(x), b);
  const rows: Row[] = [];
  for (const part of parts(body)) {
    const without = await countTokens(
      upstream,
      fix(part.without()),
      headers,
      query,
    );
    rows.push({
      kind: part.kind,
      name: part.name,
      chars: part.chars,
      tokens: full - without,
    });
  }
  const sum = rows.reduce((s, r) => s + r.tokens, 0);
  return {
    model: body.model,
    fixes: used,
    full,
    parts: sum,
    rest: full - sum,
    rows,
  };
};

/** The lines that the CLI prints for a sizing, the largest part first. */
export const sizingLines = (n: string, s: Sizing): string[] => [
  `\nrequest ${n}: ${s.full} tokens by count_tokens, parts ${s.parts}, rest ${s.rest}`,
  ...[...s.rows]
    .sort((a, b) => b.tokens - a.tokens)
    .map(
      (r) =>
        `${String(r.tokens).padStart(6)}  ${String(r.chars).padStart(6)}c  ${r.kind}  ${r.name}`,
    ),
];
